CREATE TABLE SaludMentalAtendidos (
    ID_ATENDIDOS int identity(1,1) primary key,
    Anio           INT          ,
    NroMes           INT          ,
    ubigeo     VARCHAR (6)  ,
    Departamento VARCHAR (50) ,
    Provincia   VARCHAR (100),
    Distrito      VARCHAR (100),
    Sexo          CHAR (1)     ,
    Etapa         VARCHAR (20) ,
    Diagnostico   VARCHAR (150),
    Atendidos     INT          ,
    Atenciones    INT
);

