CREATE TABLE Staging_SaludMental (
    Anio INT,
    NroMes INT,
    ubigeo VARCHAR(6),
    Departamento VARCHAR(100),
    Provincia VARCHAR(100),
    Distrito VARCHAR(100),
    Sexo CHAR(1),
    Etapa VARCHAR(20),
    Diagnostico VARCHAR(255),
    Atendidos INT,
    Atenciones INT
);
CREATE TABLE LogOperaciones (
    LogID INT IDENTITY(1,1) PRIMARY KEY,
    Fecha DATETIME DEFAULT GETDATE(),
    TipoOperacion VARCHAR(50),
    TablaAfectada VARCHAR(100),
    Usuario VARCHAR(100) DEFAULT SYSTEM_USER,
    Mensaje VARCHAR(MAX)
);

CREATE FUNCTION fn_ResumenPorDiagnostico (@DiagnosticoFiltro VARCHAR(255))
RETURNS TABLE
AS
RETURN (
    SELECT 
        Departamento,
        Diagnostico,
        SUM(Atendidos) AS TotalAtendidos,
        SUM(Atenciones) AS TotalAtenciones
    FROM SaludMentalAtendidos
    WHERE Diagnostico LIKE '%' + @DiagnosticoFiltro + '%'
    GROUP BY Departamento, Diagnostico
);

CREATE TRIGGER trg_Auditoria_SaludMental
ON SaludMentalAtendidos
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Accion VARCHAR(50);

    IF EXISTS (SELECT * FROM inserted) AND EXISTS (SELECT * FROM deleted)
        SET @Accion = 'UPDATE';
    ELSE IF EXISTS (SELECT * FROM inserted)
        SET @Accion = 'INSERT';
    ELSE IF EXISTS (SELECT * FROM deleted)
        SET @Accion = 'DELETE';
    ELSE
        RETURN;

    VALUES (
        @Accion, 
        'SaludMentalAtendidos', 
        'Operación ' + @Accion + ' ejecutada. Filas afectadas: ' + CAST(@@ROWCOUNT AS VARCHAR)
    );
END;

CREATE TRIGGER trg_Integridad_SaludMental
ON SaludMentalAtendidos
INSTEAD OF INSERT
AS
BEGIN
    SET NOCOUNT ON;

    -- Validar lógicamente que no existan valores negativos
    IF EXISTS (SELECT 1 FROM inserted WHERE Atendidos < 0 OR Atenciones < 0)
    BEGIN
        VALUES ('RECHAZO INTEGRIDAD', 'SaludMentalAtendidos', 'Intento de insertar valores negativos en métricas.');
        
        RAISERROR ('Violación de integridad: Atendidos o Atenciones no pueden ser negativos.', 16, 1);
        RETURN;
    END

    -- Insertar los registros válidos
    SELECT Anio, NroMes, ubigeo, Departamento, Provincia, Distrito, Sexo, Etapa, Diagnostico, Atendidos, Atenciones
    FROM inserted;
END;

CREATE PROCEDURE sp_IngestaUnica_SaludMental (
    @Anio INT, @NroMes INT, @ubigeo VARCHAR(6), @Departamento VARCHAR(100),
    @Provincia VARCHAR(100), @Distrito VARCHAR(100), @Sexo CHAR(1),
    @Etapa VARCHAR(20), @Diagnostico VARCHAR(255), @Atendidos INT, @Atenciones INT
)
AS
BEGIN
    SET NOCOUNT ON;
    
    BEGIN TRY
        BEGIN TRANSACTION TransaccionIngesta;
        
        -- Punto de guardado
        SAVE TRANSACTION SavepointValidacion;

        -- Validación de negocio
        IF @NroMes < 1 OR @NroMes > 12
        BEGIN
            -- Deshacemos solo hasta el savepoint si el mes es inválido
            ROLLBACK TRANSACTION SavepointValidacion;
            THROW 50001, 'El mes ingresado es inválido (debe ser entre 1 y 12).', 1;
        END

        VALUES (@Anio, @NroMes, @ubigeo, @Departamento, @Provincia, @Distrito, @Sexo, @Etapa, @Diagnostico, @Atendidos, @Atenciones);

        COMMIT TRANSACTION TransaccionIngesta;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION TransaccionIngesta;

        VALUES ('ERROR_SP', 'SaludMentalAtendidos', ERROR_MESSAGE());
        
        THROW;
    END CATCH
END;

